function parsePeople(text: string): Person[] {
  return text.trim().split('\n').map(line => {
    const values = line.split('|').map(value => value.trim())
    if (values.length !== 10 || values.some(value => !value)) throw new Error('Invalid Armenian biography row')
    const [id, name, years, category, role, bio, work, description, significance, reference] = values as [string, string, string, PersonCategory, string, string, string, string, string, string]
    const extraWorks = id === 'teryan' ? teryanWorks : {}
    return { id, name, years, category, role, bio, isArmenian: true, works: [work, ...Object.keys(extraWorks)], workInformation: { [work]: { description, significance }, ...extraWorks }, source: biographySources[id] || { name: `Վիքիպեդիա · ${name}`, url: `https://en.wikipedia.org/wiki/${encodeURIComponent(reference)}` }, portraitTitle: reference.replaceAll('_', ' '), portraitLanguage: 'en' }
  })
}

